  export function filenameFromHash(hash: number) {
      if (hash in WAD_HASHMAP)
          return WAD_HASHMAP[hash];
      let hash_str = hash.toString(16);
      const pad = '0'.repeat(8 - hash_str.length);
      return `Data/${pad}${hash_str}`;
  }
  